import random

RULE = "Route the ticket. Answer billing, technical or account."
EXAMPLES = [("Export to CSV fails", "technical"), ("Refund my plan", "billing")]
CASES = [("I was charged twice", "billing"), ("App crashes", "technical"),
         ("Change my email", "account"), ("Pricing page is blank", "technical")]


def build_system(examples):
    return RULE + "".join(f"\n{t} -> {q}" for t, q in examples)


def accuracy(system, cases):
    rng = random.Random(len(system))
    return sum(rng.random() < 0.9 for _ in cases) / len(cases)
